impl DbUpdate {
    fn with_table_capacity(hint: usize) -> Self {
        Self {
            tables: Vec::with_capacity(hint.min(327)),
        }
    }
    fn append(&mut self, update: __DbTableUpdate) {
        match self
            .tables
            .binary_search_by_key(&update.order(), __DbTableUpdate::order)
        {
            Ok(index) => self.tables[index].append(update),
            Err(index) => self.tables.insert(index, update),
        }
    }
}

